package com.bank.sdlc.method;

import com.bank.sdlc.model.SdlcPhase;
import com.bank.sdlc.track.DeliveryTracker;
import java.util.logging.Logger;

// Runs each SDLC phase ONCE, sequentially, for the WHOLE feature.
public class Waterfall implements Methodology {
    private static final Logger log = Logger.getLogger(Waterfall.class.getName());

    @Override
    public void runProject(DeliveryTracker tracker) {
        int week = 0;
        for (SdlcPhase phase : SdlcPhase.values()) {
            if (phase == SdlcPhase.MAINTENANCE) break;
            week += 2; // each big phase takes ~2 weeks
            log.info(() -> "Waterfall: whole feature in phase " + phase);
        }
        // Working software only exists after DEPLOYMENT, near the end.
        tracker.recordFirstDelivery(name(), week);
    }

    @Override
    public void handleRequirementChange(DeliveryTracker tracker, int atWeek) {
        // A change found mid-project forces revisiting earlier phases — expensive.
        log.warning(() -> "Waterfall: change at week " + atWeek
                + " → must revisit DESIGN + IMPLEMENTATION (costly rework)");
        tracker.recordChangeCost(name(), "high (reopen completed phases)");
    }

    @Override public String name() { return "Waterfall"; }
}
