package com.bank.sdlc.method;

import com.bank.sdlc.model.SdlcPhase;
import com.bank.sdlc.track.DeliveryTracker;
import java.util.List;
import java.util.logging.Logger;

// Runs ALL SDLC phases within each short sprint, one slice at a time.
public class Agile implements Methodology {
    private static final Logger log = Logger.getLogger(Agile.class.getName());
    private final List<String> slices;

    public Agile(List<String> slices) { this.slices = slices; }

    @Override
    public void runProject(DeliveryTracker tracker) {
        int week = 0;
        boolean firstDeliveryRecorded = false;
        for (String slice : slices) {
            week += 2; // one 2-week sprint per slice
            // Each sprint touches requirements→design→build→test→deploy for THIS slice.
            for (SdlcPhase phase : SdlcPhase.values()) {
                if (phase == SdlcPhase.MAINTENANCE) break;
            }
            log.info(() -> "Agile sprint delivered slice '" + slice + "' (shippable increment)");
            if (!firstDeliveryRecorded) {
                tracker.recordFirstDelivery(name(), week); // usable software after sprint 1
                firstDeliveryRecorded = true;
            }
        }
    }

    @Override
    public void handleRequirementChange(DeliveryTracker tracker, int atWeek) {
        // A change simply becomes a backlog item for the next sprint — cheap.
        log.info(() -> "Agile: change at week " + atWeek
                + " → added to backlog, absorbed in next sprint");
        tracker.recordChangeCost(name(), "low (reprioritize next sprint)");
    }

    @Override public String name() { return "Agile"; }
}
