package com.bank.sdlc.track;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.logging.Logger;

// Records when working software first appears and the cost of change.
public class DeliveryTracker {
    private static final Logger log = Logger.getLogger(DeliveryTracker.class.getName());
    private final Map<String, Integer> firstDeliveryWeek = new LinkedHashMap<>();
    private final Map<String, String> changeCost = new LinkedHashMap<>();

    public void recordFirstDelivery(String method, int week) {
        firstDeliveryWeek.put(method, week);
        log.info(() -> method + ": first working software at week " + week);
    }

    public void recordChangeCost(String method, String cost) {
        changeCost.put(method, cost);
    }

    public void summary() {
        firstDeliveryWeek.forEach((m, w) ->
            log.info(() -> m + " → first delivery week " + w
                    + ", change cost " + changeCost.getOrDefault(m, "n/a")));
    }
}
