package com.bank.sdlc;

import com.bank.sdlc.method.Agile;
import com.bank.sdlc.method.Methodology;
import com.bank.sdlc.method.Waterfall;
import com.bank.sdlc.track.DeliveryTracker;
import java.util.List;

public class DeliveryDemo {
    public static void main(String[] args) {
        DeliveryTracker tracker = new DeliveryTracker();
        List<String> slices = List.of("application-form", "credit-check",
                                      "document-upload", "approval");

        // Same loan feature, two methodologies over the same SDLC phases.
        Methodology waterfall = new Waterfall();
        waterfall.runProject(tracker);
        waterfall.handleRequirementChange(tracker, 7); // change discovered late

        Methodology agile = new Agile(slices);
        agile.runProject(tracker);
        agile.handleRequirementChange(tracker, 5);      // change mid-project

        tracker.summary();
    }
}
